+  assert.equal(wordCount('naïve'), 1);
+  assert.equal(wordCount('Привет'), 1);
+  assert.equal(wordCount('καλημέρα κόσμε'), 2);
+  assert.equal(wordCount('2024'), 1);
+});
+
+test('returns 0 for a long string made only of punctuation and symbols', () => {
+  assert.equal(wordCount('!?.,;:—–-\'’/_ '.repeat(200)), 0);
+});

